package com.runetrivia;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.ConfigSection;

@ConfigGroup("runetrivia")
public interface RuneTriviaConfig extends Config
{
    /**
     * How the host NPC's speech is rendered.
     *   OVERHEAD_PIXEL — yellow OSRS pixel font with black drop shadow,
     *                    floating above the NPC's head. No bubble. Matches
     *                    authentic overhead chat style.
     *   BUBBLE         — rounded white panel with a tail (the original
     *                    Phase 5 style). Useful for longer lines that need
     *                    to wrap inside a defined area.
     */
    enum HostSpeechStyle
    {
        OVERHEAD_PIXEL,
        BUBBLE
    }

    // ====================================================================
    // Section headers — order here = order in the config panel.
    // ====================================================================

    @ConfigSection(
        name = "Challenges",
        description = "How other players can challenge you, and what cues you get when they do.",
        position = 0
    )
    String challengesSection = "challenges";

    @ConfigSection(
        name = "Host NPC",
        description = "The trivia host that spawns during a match.",
        position = 1
    )
    String hostNpcSection = "hostNpc";

    @ConfigSection(
        name = "Match feedback",
        description = "Sounds + celebration cues during a match.",
        position = 2
    )
    String matchFeedbackSection = "matchFeedback";

    @ConfigSection(
        name = "Arena visuals",
        description = "World overlays drawn around the host during a match.",
        position = 3
    )
    String arenaVisualsSection = "arenaVisuals";

    @ConfigSection(
        name = "Connection",
        description = "Backend endpoints. Defaults match the production server — only change these if you're running a local RuneTrivia server for development.",
        position = 99,
        closedByDefault = true
    )
    String connectionSection = "connection";

    // ====================================================================
    // Challenges
    // ====================================================================

    @ConfigItem(
        keyName = "acceptingChallenges",
        name = "Accept incoming challenges",
        description = "When off, other players will see you as 'refusing challenges'",
        section = challengesSection,
        position = 0
    )
    default boolean acceptingChallenges()
    {
        return true;
    }

    @ConfigItem(
        keyName = "enableRightClickChallenge",
        name = "Right-click to challenge",
        description = "Adds a 'Challenge to Trivia' option to player right-click menus",
        section = challengesSection,
        position = 1
    )
    default boolean enableRightClickChallenge()
    {
        return true;
    }

    @ConfigItem(
        keyName = "challengeMenuRequiresShift",
        name = "Only show on shift+right-click",
        description = "Hide the 'Challenge to Trivia' menu entry from the regular right-click menu; only show it when shift is held",
        section = challengesSection,
        position = 2
    )
    default boolean challengeMenuRequiresShift()
    {
        return false;
    }

    @ConfigItem(
        keyName = "showChallengeBanner",
        name = "Challenge banner overlay",
        description = "Floating in-game banner when a challenge arrives. Auto-dismisses on response.",
        section = challengesSection,
        position = 3
    )
    default boolean showChallengeBanner()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showChallengerHintArrow",
        name = "Hint arrow over challenger",
        description = "Show the engine hint arrow over the player who challenged you (world + minimap).",
        section = challengesSection,
        position = 4
    )
    default boolean showChallengerHintArrow()
    {
        return true;
    }

    @ConfigItem(
        keyName = "playChallengeChime",
        name = "Challenge chime",
        description = "Play a soft chime when someone challenges you to trivia.",
        section = challengesSection,
        position = 5
    )
    default boolean playChallengeChime()
    {
        return true;
    }

    @ConfigItem(
        keyName = "challengeChimeId",
        name = "Challenge chime sound ID",
        description = "Sound effect ID for the challenge chime. Try 71, 1444, 2581.",
        section = challengesSection,
        position = 6
    )
    default int challengeChimeId()
    {
        return 71;
    }

    // ====================================================================
    // Host NPC
    // ====================================================================

    @ConfigItem(
        keyName = "showHostNpc",
        name = "Show host NPC",
        description = "Render the client-side trivia host NPC during matches",
        section = hostNpcSection,
        position = 0
    )
    default boolean showHostNpc()
    {
        return true;
    }

    @ConfigItem(
        keyName = "showHostLabel",
        name = "Show host name label",
        description = "Draw the gold name label floating above the host NPC's tile. Off by default — the NPC's own overhead nameplate already identifies them.",
        section = hostNpcSection,
        position = 1
    )
    default boolean showHostLabel()
    {
        return false;
    }

    @ConfigItem(
        keyName = "playOverheadBanter",
        name = "Host overhead banter",
        description = "Let the host NPC say flavour lines as overhead chat between questions",
        section = hostNpcSection,
        position = 2
    )
    default boolean playOverheadBanter()
    {
        return true;
    }

    @ConfigItem(
        keyName = "hostSpeechStyle",
        name = "Host speech style",
        description = "OVERHEAD_PIXEL = authentic yellow pixel text above the NPC. BUBBLE = rounded panel.",
        section = hostNpcSection,
        position = 3
    )
    default HostSpeechStyle hostSpeechStyle()
    {
        return HostSpeechStyle.OVERHEAD_PIXEL;
    }

    // ====================================================================
    // Match feedback
    // --------------------------------------------------------------------
    // Sound IDs — use 0 to disable. Candidate IDs you can iterate against
    // in-game:
    //   71    UI pickup pip       (subtle)
    //   1444  bell ding           (light alert)
    //   2396  level-up jingle     (already used for winner celebration)
    //   2581  "what's this?" tone (museum-ish)
    //   3884  shorter chime       (try as 'correct')
    //   4475  longer chime        (try as 'all-correct')
    // The Varrock Museum natural-history-quiz chime isn't in RuneLite's
    // named SoundEffectID constants — best approach is to flip between
    // the candidates above in-game and pick what sounds right.
    // ====================================================================

    @ConfigItem(
        keyName = "playWinnerCelebration",
        name = "Winner celebration",
        description = "Play OSRS level-up fireworks + chime over the winner when a match ends",
        section = matchFeedbackSection,
        position = 0
    )
    default boolean playWinnerCelebration()
    {
        return true;
    }

    @ConfigItem(
        keyName = "questionSoundId",
        name = "Question sound ID",
        description = "Sound effect played when a question is delivered. 0 = off. Try 71, 1444, 2581.",
        section = matchFeedbackSection,
        position = 1
    )
    default int questionSoundId()
    {
        return 0;
    }

    @ConfigItem(
        keyName = "correctSoundId",
        name = "Correct answer sound ID",
        description = "Sound effect played when a player gets the question right. 0 = off. Default 2309 is the OSRS quiz_correct chime.",
        section = matchFeedbackSection,
        position = 2
    )
    default int correctSoundId()
    {
        return 2309;
    }

    // ====================================================================
    // Arena visuals
    // ====================================================================

    @ConfigItem(
        keyName = "showArenaTileMat",
        name = "Highlight arena tiles",
        description = "Draw the square of highlighted tiles around the host. Off by default — the engine hint arrow + host NPC already mark the arena.",
        section = arenaVisualsSection,
        position = 0
    )
    default boolean showArenaTileMat()
    {
        return false;
    }

    // ====================================================================
    // Connection
    // --------------------------------------------------------------------
    // Editable text fields, default to the production server. For local
    // development, change to ws://localhost:8080/ws + http://localhost:8080
    // in the in-game settings panel (one-time edit per RuneLite profile).
    // If a user accidentally breaks one, right-click the field → "Reset"
    // restores the default. The Connection section is collapsed by default
    // so casual players never see these unless they go looking.
    // ====================================================================

    @ConfigItem(
        keyName = "backendUrl",
        name = "Backend WebSocket URL",
        description = "WebSocket endpoint for the RuneTrivia server. Right-click → Reset to restore the default.",
        section = connectionSection,
        position = 0
    )
    default String backendUrl()
    {
        return "wss://api.runetrivia.com/ws";
    }

    @ConfigItem(
        keyName = "apiUrl",
        name = "Backend REST URL",
        description = "HTTP base for fetching match history. Right-click → Reset to restore the default.",
        section = connectionSection,
        position = 1
    )
    default String apiUrl()
    {
        return "https://api.runetrivia.com";
    }
}

package com.runetrivia;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.inject.Provides;
import com.runetrivia.match.ArenaTileFinder;
import com.runetrivia.match.HostLines;
import com.runetrivia.match.HostNpcRenderer;
import com.runetrivia.match.MatchSession;
import com.runetrivia.net.TriviaWsClient;
import com.runetrivia.net.messages.Domain;
import com.runetrivia.net.messages.Messages;
import com.runetrivia.ui.ArenaTileOverlay;
import com.runetrivia.ui.HostSpeechOverlay;
import com.runetrivia.ui.IncomingChallengeBanner;
import com.runetrivia.ui.TriviaPanel;
import com.runetrivia.ui.TriviaQuestionOverlay;
import java.awt.Color;
import net.runelite.client.util.ImageUtil;
import java.io.IOException;
import java.util.ArrayList;
