    /**
     * Send MATCH_FORFEIT to the server. Used by both the side-panel button
     * and the ::forfeit chat command. No-op when there's no active match.
     */
    private void sendForfeit(String reason)
    {
        MatchSession s = activeMatch;
        if (s == null || s.matchId == null) return;
        Messages.MatchForfeitPayload p = new Messages.MatchForfeitPayload();
        p.matchId = s.matchId;
        p.reason = reason;
        wsClient.send(Messages.TYPE_MATCH_FORFEIT, p);
        log.info("local forfeit sent for match {} (reason={})", s.matchId, reason);
    }

    // -- TriviaWsClient.Listener ------------------------------------------

    @Override
    public void onStatusChange(TriviaWsClient.Status status)
    {
        if (panel != null)
        {
            panel.setStatus(status);
        }
    }

    @Override
    public void onMessage(String type, String id, JsonElement payload)
    {
        switch (type)
        {
            case Messages.TYPE_CHALLENGE_OFFERED:
            {
                Messages.ChallengeOfferedPayload p = gson.fromJson(payload, Messages.ChallengeOfferedPayload.class);
                handleIncomingChallenge(p);
                return;
            }
            case Messages.TYPE_CHALLENGE_RESOLVED:
            {
                Messages.ChallengeResolvedPayload p = gson.fromJson(payload, Messages.ChallengeResolvedPayload.class);
                handleChallengeResolved(p);
                return;
            }
            case Messages.TYPE_ARENA_STAGED:
            {
                Messages.ArenaStagedPayload p = gson.fromJson(payload, Messages.ArenaStagedPayload.class);
                handleArenaStaged(p);
                return;
            }
            case Messages.TYPE_MATCH_STARTED:
            {
                Messages.MatchStartedPayload p = gson.fromJson(payload, Messages.MatchStartedPayload.class);
                handleMatchStarted(p);
                return;
            }
            case Messages.TYPE_QUESTION_DELIVERED:
            {
                Messages.QuestionDeliveredPayload p = gson.fromJson(payload, Messages.QuestionDeliveredPayload.class);
                handleQuestionDelivered(p);
                return;
            }
            case Messages.TYPE_QUESTION_RESOLVED:
            {
                Messages.QuestionResolvedPayload p = gson.fromJson(payload, Messages.QuestionResolvedPayload.class);
                handleQuestionResolved(p);
                return;
            }
            case Messages.TYPE_MATCH_COMPLETED:
            {
                Messages.MatchCompletedPayload p = gson.fromJson(payload, Messages.MatchCompletedPayload.class);
                handleMatchCompleted(p);
                return;
            }
            case Messages.TYPE_MATCH_FORFEIT:
            {
                Messages.MatchForfeitPayload p = gson.fromJson(payload, Messages.MatchForfeitPayload.class);
                handleMatchForfeit(p);
                return;
            }
            case Messages.TYPE_BANTER:
            {
                Messages.BanterPayload p = gson.fromJson(payload, Messages.BanterPayload.class);
                handleBanter(p);
                return;
            }
            case Messages.TYPE_SHAME_PLAYER:
            {
                Messages.ShamePlayerPayload p = gson.fromJson(payload, Messages.ShamePlayerPayload.class);
                handleShamePlayer(p);
                return;
            }
            case Messages.TYPE_CHALLENGE_CREATED:
            case Messages.TYPE_WELCOME:
            case Messages.TYPE_PONG:
            case Messages.TYPE_ERROR:
                // Status / confirmation frames; nothing actionable here.
                return;
            default:
                log.debug("unhandled message type: {}", type);
        }
    }

    private void handleIncomingChallenge(Messages.ChallengeOfferedPayload p)
    {
        // We arrive here on the OkHttp dispatcher thread (from WS onMessage).
        // Local range validation reads client.getLocalPlayer().getWorldLocation(),
        // which RuneLite enforces as client-thread-only (assertion failure off-thread).
        clientThread.invoke(() ->
        {
            Player me = client.getLocalPlayer();
            if (me != null && me.getWorldLocation() != null
                && p.proposedArena != null
                && me.getWorldLocation().getRegionID() != p.proposedArena.regionId)
            {
                log.info("auto-declining challenge {}: not in same region (mine={}, theirs={})",
                    p.challengeId, me.getWorldLocation().getRegionID(), p.proposedArena.regionId);
                Messages.ChallengeRespondPayload reply = new Messages.ChallengeRespondPayload();
                reply.challengeId = p.challengeId;
                reply.accept = false;
                wsClient.send(Messages.TYPE_CHALLENGE_RESPOND, reply);
                return;
            }
            // Track the pending challenge so the banner overlay, hint arrow,
            // and ::accept/::decline chat commands all have something to act on.
            pendingIncomingChallengeId = p.challengeId;
            pendingIncomingChallengerDisplay = p.fromDisplayName;
            panel.renderPending(p.challengeId, p.fromDisplayName);

            // Chat-line baseline notification. Always on — non-aggressive and
            // persists in chat history for later review. Orange to differentiate
            // from the other chat color slots (yellow=system, purple=trade,
            // red=RuneLite alerts, green=clan, white=default).
            String formatted = new ChatMessageBuilder()
                .append(RUNE_TRIVIA_CHAT,
                    "RuneTrivia: " + p.fromDisplayName
                    + " has challenged you to a match! "
                    + "Open the side panel or type ::accept / ::decline.")
                .build();
            client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", formatted, null);

            // Soft chime (config-gated). Plays locally only — no broadcast.
            if (config.playChallengeChime())
            {
                playSfx(config.challengeChimeId());
            }
            // updateHintArrow runs every GameTick and will pick up the new
            // pendingIncomingChallengerDisplay on its next pass.
        });
    }

    private void handleChallengeResolved(Messages.ChallengeResolvedPayload p)
    {
        panel.renderPending(null, null);
        // Clear pending-incoming state so the banner overlay vanishes and
        // the next updateHintArrow tick clears the arrow.
        if (p.challengeId != null && p.challengeId.equals(pendingIncomingChallengeId))
        {
            pendingIncomingChallengeId = null;
            pendingIncomingChallengerDisplay = null;
        }
        log.info("challenge {} resolved: accepted={} reason={}",
            p.challengeId, p.accepted, p.reason);

        // Only update the outgoing-challenge panel if we have one in flight.
        // (CHALLENGE_RESOLVED is broadcast to both parties, so we'd otherwise
        // clobber the incoming side with the outgoing label.)
        if (outgoingTargetDisplay != null)
        {
            String target = outgoingTargetDisplay;
            String msg;
            if (p.accepted)
            {
                msg = "Challenge accepted! Match starting…";
            }
            else
            {
                msg = "Challenge ended: " + humanReason(p.reason);
            }
            panel.renderOutgoing(target, msg);
            outgoingTargetDisplay = null;
            // Auto-clear the panel after a few seconds so it doesn't sit stale.
            new java.util.Timer(true).schedule(new java.util.TimerTask()
            {
                @Override
                public void run()
                {
                    if (panel != null)
                    {
                        panel.renderOutgoing(null, null);
                    }
                }
            }, 6000);
        }
        // TODO: phase 4 — if accepted, transition to staging UI.
    }

    // -- Match lifecycle handlers (Phase 4) -------------------------------

    private void handleArenaStaged(Messages.ArenaStagedPayload p)
    {
        // Touches client.getLocalPlayer() and stores per-tile data we'll
        // later read from the game thread; do all of it under the client thread.
        clientThread.invoke(() ->
        {
            Player me = client.getLocalPlayer();
            String myDisplay = me == null ? null : me.getName();
            if (myDisplay == null)
            {
                log.warn("ARENA_STAGED arrived but local player not loaded; can't bind match");
                return;
            }
            MatchSession session = MatchSession.fromArenaStaged(
                p.matchId, p.regionId, p.host, p.tiles, p.stagingDeadline, myDisplay);
            if (session == null)
            {
                log.warn("ARENA_STAGED tiles did not include local player {} (keys={})",
                    myDisplay, p.tiles == null ? "null" : p.tiles.keySet());
                return;
            }
            activeMatch = session;
            // Outgoing-challenge UI is no longer relevant once we're staging.
            outgoingTargetDisplay = null;
            panel.renderOutgoing(null, null);
            renderActiveMatchPanel();
            log.info("match {} staged in region {}; my tile={} opponent tile={}",
                p.matchId, p.regionId, session.myAssignedTile, session.opponentAssignedTile);
            // Try to spawn the visible NPC (gated by config). Retries happen
            // every GameTick until the model parts have loaded.
            if (config.showHostNpc() && session.host != null && session.host.tile != null)
            {
                // Per-NPC idle / walk animation overrides via host_lines JSON.
                int idleAnim = hostLines.getInt(
                    session.host.displayName, "idleAnimation", HostNpcRenderer.DEFAULT_IDLE_ANIM);
                int walkAnim = hostLines.getInt(
                    session.host.displayName, "walkAnimation", HostNpcRenderer.DEFAULT_WALK_ANIM);
                hostNpcRenderer.setIdleAnimation(idleAnim);
                hostNpcRenderer.setWalkAnimation(walkAnim);
                // Spawn off-arena and walk in. The host "arrives" rather than
                // pops into existence on the host tile. Bow + welcome line
                // both fire once they're standing on the final tile — the
                // text used to appear mid-walk, which broke the illusion that
                // the host is the one speaking.
                Domain.WorldPoint dest = session.host.tile;
                Domain.WorldPoint walkInFrom = walkInOriginFor(dest);
                hostNpcRenderer.requestSpawn(session.host.npcId, walkInFrom);
                // Bow + welcome fire exactly when the host arrives — the
                // callback runs on the client thread from advanceWalkSegment,
                // so no Timer race with the walk's actual completion.
                hostNpcRenderer.walkTo(dest, () ->
                {
                    hostNpcRenderer.playReaction(ANIM_BOW, 1_000);
                    sayCategory("welcome", null);
                });
            }
            else
            {
                // No host NPC configured — say it immediately so the player
                // still sees the welcome line.
                sayCategory("welcome", null);
            }
        });
    }

    private void handleMatchStarted(Messages.MatchStartedPayload p)
    {
        clientThread.invoke(() ->
        {
            MatchSession session = activeMatch;
            if (session == null || !p.matchId.equals(session.matchId)) return;
            session.markStarted(null);
            // Fresh match = fresh wiki-trigger budget. (We don't want the
            // previous match's trigger to suppress detection in this one.)
            wikiTriggeredForCurrentMatch = false;
            renderActiveMatchPanel();
            log.info("match {} started", p.matchId);
            Map<String, String> getReadyVars = new HashMap<>();
            getReadyVars.put("opponent1", session.myDisplayName);
            getReadyVars.put("opponent2", session.opponentDisplayName);
            // The server fires MATCH_STARTED the moment both players are
            // ready, which is typically ~1s into a ~3s host walk-in. Saying
            // "get ready" while the host is still mid-stride breaks the
            // illusion that the host is the one speaking — defer it until
            // they've planted their feet.
            hostNpcRenderer.whenArrived(() -> sayCategory("getReady", getReadyVars));
        });
    }

    private void handleQuestionDelivered(Messages.QuestionDeliveredPayload p)
    {
        clientThread.invoke(() ->
        {
            MatchSession session = activeMatch;
            if (session == null || !p.matchId.equals(session.matchId)) return;
            log.info("question {} delivered: {}", p.questionIndex, p.prompt);
            Map<String, String> qVars = new HashMap<>();
            qVars.put("q", String.valueOf(p.questionIndex + 1));
            String intro = hostLines.pick(hostName(), "questionIntro", qVars);
            // The intro is a brief flavor lead-in; we always append the actual
            // prompt below so the player can read it from the bubble too (the
            // overlay banner shows it for the full 30s).
            String bubble = (intro == null || intro.isEmpty())
                ? "Question " + (p.questionIndex + 1) + ": " + p.prompt
                : intro + "\n" + p.prompt;
            // Defer the on-screen banner + reaction + sound until the host
            // actually starts saying the line. Without this, QUESTION_DELIVERED
            // races ahead of the host's speech queue (welcome → getReady →
            // intro) and the question appears mid-walk-in monologue. The
            // overlay's say(line, onInstalled) fires the callback the moment
            // this line becomes the visible one.
            //
            // Trade-off: a small slice of the server-side response deadline
            // (~5s for the first question of the match) is consumed by the
            // host's intro sequence. Acceptable for the cinematic pacing;
            // can be reclaimed by adding a server-side first-question delay
            // later if needed.
            hostSay(bubble, () -> clientThread.invoke(() ->
            {
                MatchSession s2 = activeMatch;
                if (s2 == null || !p.matchId.equals(s2.matchId)) return;
                s2.setCurrentQuestion(p.questionIndex, p.prompt, p.deadline);
                renderActiveMatchPanel();
                hostNpcRenderer.playReaction(ANIM_THINK, 2_500);
                playSfx(config.questionSoundId());
            }));
        });
    }

    private void handleQuestionResolved(Messages.QuestionResolvedPayload p)
    {
        clientThread.invoke(() ->
        {
            MatchSession session = activeMatch;
            if (session == null || !p.matchId.equals(session.matchId)) return;
            session.applyResolution(p.results, p.scores, p.canonicalAnswer);
            renderActiveMatchPanel();
            log.info("question {} resolved: canonical={} correct={}",
                p.questionIndex, p.canonicalAnswer, session.getLastCorrectDisplay());
            String correct = session.getLastCorrectDisplay();
            Map<String, String> resVars = new HashMap<>();
            resVars.put("answer", p.canonicalAnswer == null ? "" : p.canonicalAnswer);
            if (correct != null)
            {
                resVars.put("player", correct);
                sayCategory("correctReaction", resVars);
                hostNpcRenderer.playReaction(ANIM_CHEER, 2_500);
                playSfx(config.correctSoundId());
            }
            else
            {
                sayCategory("noOneGot", resVars);
                hostNpcRenderer.playReaction(ANIM_SHRUG, 2_500);
            }
        });
    }

    /**
     * Play a sound effect by ID, swallowing any exception. id <= 0 is a
     * no-op so users can disable sounds by clearing the config field.
     * Must be called on the client thread.
     */
    private void playSfx(int id)
    {
        if (id <= 0) return;
        try { client.playSoundEffect(id); }
        catch (Exception e) { log.debug("playSoundEffect({}) threw: {}", id, e.toString()); }
    }

    private void handleMatchCompleted(Messages.MatchCompletedPayload p)
    {
        clientThread.invoke(() ->
        {
            MatchSession session = activeMatch;
            if (session == null || !p.matchId.equals(session.matchId)) return;
            session.markComplete();
            renderActiveMatchPanel();
            log.info("match {} complete: winner={} reason={}",
                p.matchId, p.winnerDisplayName, p.reason);
            Map<String, String> endVars = new HashMap<>();
            if (p.winnerDisplayName != null)
            {
                endVars.put("winner", p.winnerDisplayName);
                String loser = p.winnerDisplayName.equalsIgnoreCase(session.myDisplayName)
                    ? session.opponentDisplayName : session.myDisplayName;
                endVars.put("loser", loser);
                sayCategory("winnerCelebration", endVars);
                hostNpcRenderer.playReaction(ANIM_CHEER, 3_000);
                if (config.playWinnerCelebration())
                {
                    celebrateWinner(p.winnerDisplayName);
                }
            }
            else
            {
                endVars.put("opponent1", session.myDisplayName);
                endVars.put("opponent2", session.opponentDisplayName);
                sayCategory("draw", endVars);
                hostNpcRenderer.playReaction(ANIM_SHRUG, 3_000);
            }
            refreshMatchHistory();
            // Farewell sequence: cheer/shrug (3s) -> wave (1.5s) ->
            // walk away off the arena (2s) -> despawn. Total ~6.5s.
            // Gives the host a grounded exit instead of vanishing in place.
            scheduleHostExit(session.host == null ? null : session.host.tile);
            scheduleClearActiveMatch(p.matchId);
        });
    }

    private void handleMatchForfeit(Messages.MatchForfeitPayload p)
    {
        clientThread.invoke(() ->
        {
            MatchSession session = activeMatch;
            if (session == null || !p.matchId.equals(session.matchId)) return;
            session.markComplete();
            renderActiveMatchPanel();
            log.info("match {} forfeited: {}", p.matchId, p.reason);
            hostSay("The match has been forfeited (" + p.reason + ").");
            // Forfeit is a "things ended awkwardly" moment — keep the NPC for
            // a brief beat then despawn (no celebration animation).
            scheduleDespawnHost(2_000);
            refreshMatchHistory();
            scheduleClearActiveMatch(p.matchId);
        });
    }

    /**
     * Trigger the OSRS level-up fireworks graphic + chime over the named
     * winner. Both clients call this independently; each one looks up the
     * winner among its locally cached players. If the winner isn't in render
     * distance (e.g. they walked off), the graphic silently no-ops but the
     * chime still plays — so the local player at least hears the win state.
     *
     * Must be called on the client thread (the MATCH_COMPLETED handler is
     * already wrapped).
     */
    private void celebrateWinner(String winnerDisplayName)
    {
        // OSRS shared IDs. Both stable across cache revisions.
        final int LEVEL_UP_GRAPHIC = 199;          // firework burst
        final int LEVEL_UP_GRAPHIC_HEIGHT = 84;    // about head-height for a player
        final int LEVEL_UP_SOUND = 2396;           // level-up jingle

        // Local chime so we hear the win regardless of camera position.
        try { client.playSoundEffect(LEVEL_UP_SOUND); }
        catch (Exception e) { log.debug("playSoundEffect threw: {}", e.toString()); }

        // Find the winner among visible players and fire fireworks over them.
        String winnerNorm = com.runetrivia.util.NameUtil.normalize(winnerDisplayName);
        for (Player p : client.getPlayers())
        {
            if (p == null || p.getName() == null) continue;
            if (!com.runetrivia.util.NameUtil.normalize(p.getName()).equals(winnerNorm)) continue;
            try
            {
                p.setGraphic(LEVEL_UP_GRAPHIC);
                p.setGraphicHeight(LEVEL_UP_GRAPHIC_HEIGHT);
                p.setSpotAnimFrame(0);
            }
            catch (Exception e)
            {
                log.debug("setGraphic threw for winner {}: {}", winnerDisplayName, e.toString());
            }
            log.info("celebrating winner {} with fireworks", winnerDisplayName);
            return;
        }
        log.info("winner {} not in render distance for fireworks (chime still played)", winnerDisplayName);
    }

    /**
     * Schedule the host NPC to despawn after {@code delayMs}. Used for the
     * abrupt forfeit case; see {@link #scheduleHostExit} for the natural
     * match-end farewell sequence.
     */
    private void scheduleDespawnHost(long delayMs)
    {
        new java.util.Timer(true).schedule(new java.util.TimerTask()
        {
            @Override
            public void run()
            {
                hostNpcRenderer.requestDespawn();
            }
        }, delayMs);
    }

    /**
     * Multi-stage host exit: wave goodbye, walk a few tiles off the arena,
     * then despawn. Looks much more grounded than an in-place wave + vanish.
     *
     * Timing (relative to call):
     *   t=0      cheer/shrug reaction already playing (started by caller)
     *   t=4.5s   wave goodbye
     *   t=6.0s   clear the speech bubble + start walk-out toward
     *            {@link #walkOutDestinationFor}
     *   t=~8.4s  despawn (walk complete)
     *
     * We bumped the wave delay from 3s -> 4.5s and explicitly clear the
     * bubble at walk start: the bubble is anchored to the original host
     * tile (not the moving NPC), so a lingering line would visually float
     * at an empty square as the host strolls away. Clearing it the moment
     * the host's feet move keeps the staging consistent.
     */
    private void scheduleHostExit(Domain.WorldPoint hostTile)
    {
        final long waveDelay = 4_500;
        final long waveDuration = 1_500;
        final long walkStart = waveDelay + waveDuration;     // 6000

        scheduleAfter(waveDelay, () -> hostNpcRenderer.playReaction(ANIM_WAVE, waveDuration));
        if (hostTile != null)
        {
            Domain.WorldPoint exit = walkInOriginFor(hostTile); // same tile as walk-in
            // Despawn runs as the walk-out arrival callback, so it fires the
            // moment the host actually reaches the exit tile — no Timer race
            // with the walk's true duration (which is tile-paced and can vary
            // by up to one game tick depending on alignment with GameTick).
            scheduleAfter(walkStart, () ->
            {
                speechOverlay.clear();
                hostNpcRenderer.walkTo(exit, () -> hostNpcRenderer.requestDespawn());
            });
        }
        else
        {
            // No host tile (defensive) — just clear text + despawn after the wave.
            scheduleAfter(walkStart + 500, () ->
            {
                speechOverlay.clear();
                hostNpcRenderer.requestDespawn();
            });
        }
    }

    /**
     * Pick the spawn/exit tile relative to the host's resting tile. We use a
     * fixed offset south of the host. Doesn't check collision — if a wall
     * happens to be in the way the host walks through it visually, but since
     * RuneLiteObjects don't interact with terrain pathing this is harmless.
     */
    private static Domain.WorldPoint walkInOriginFor(Domain.WorldPoint hostTile)
    {
        return new Domain.WorldPoint(hostTile.x, hostTile.y - WALK_OFFSET_TILES, hostTile.plane);
    }

    /** Daemon Timer convenience for scheduling a Runnable after a delay. */
    private static void scheduleAfter(long delayMs, Runnable r)
    {
        new java.util.Timer(true).schedule(new java.util.TimerTask()
        {
            @Override
            public void run() { r.run(); }
        }, delayMs);
    }

    /**
     * Append a chat line styled to look like the host NPC speaking. Uses
     * GAMEMESSAGE channel so it appears in the player's main chat tab and
     * is reviewable in history.
     *
     * Must be called on the client thread (the message handlers above already
     * wrap in {@link ClientThread#invoke}).
     */
    private void handleBanter(Messages.BanterPayload p)
    {
        clientThread.invoke(() ->
        {
            MatchSession session = activeMatch;
            if (session == null || !p.matchId.equals(session.matchId)) return;
            if (!"struggling".equalsIgnoreCase(p.kind)) return;
            // Map the named "struggling" player to (player, opponent) for line
            // interpolation. The host taunts the strugger by encouraging the
            // opponent — so {player}=who's struggling, {opponent}=the other.
            String strugglerNorm = com.runetrivia.util.NameUtil.normalize(p.displayName);
            String playerDisplay;
            String opponentDisplay;
            if (strugglerNorm.equals(session.myNormalized))
            {
                playerDisplay = session.myDisplayName;
                opponentDisplay = session.opponentDisplayName;
            }
            else if (strugglerNorm.equals(session.opponentNormalized))
            {
                playerDisplay = session.opponentDisplayName;
                opponentDisplay = session.myDisplayName;
            }
            else
            {
                log.debug("BANTER for unknown player {} (mine={}, opponent={})",
                    p.displayName, session.myDisplayName, session.opponentDisplayName);
                return;
            }
            Map<String, String> vars = new HashMap<>();
            vars.put("player", playerDisplay);
            vars.put("opponent", opponentDisplay);
            sayCategory("playerStruggling", vars);
            // Host laughs at the struggle — teasing energy.
            hostNpcRenderer.playReaction(ANIM_LAUGH, 2_000);
            log.info("banter struggling: {} -> taunt opponent {}", playerDisplay, opponentDisplay);
        });
    }

    /**
     * Server says someone in this match was caught using the wiki. Apply
     * the clown-suit override for the announced duration and have the host
     * deliver a mocking line. The actual forfeit + match teardown arrives
     * shortly after as MATCH_COMPLETED with reason=forfeit; this handler
     * just owns the shame ceremony.
     */
    private void handleShamePlayer(Messages.ShamePlayerPayload p)
    {
        clientThread.invoke(() ->
        {
            outfitOverride.shame(p.cheaterDisplayName, p.durationMs);
            Map<String, String> vars = new HashMap<>();
            vars.put("cheater", p.cheaterDisplayName);
            sayCategory("cheaterShamed", vars);
            log.info("SHAME applied to {} for {}ms", p.cheaterDisplayName, p.durationMs);
        });
    }

    /** Active host's display name (or a generic fallback if no match is active). */
    private String hostName()
    {
        MatchSession session = activeMatch;
        return (session != null && session.host != null && session.host.displayName != null)
            ? session.host.displayName
            : "Trivia Host";
    }

    /**
     * Convenience: pick a line from the named category for the current host
     * and route it through {@link #hostSay(String)}. If the host or category
     * isn't found, silently no-ops (and logs at debug).
     */
    private void sayCategory(String category, Map<String, String> vars)
    {
        String line = hostLines.pick(hostName(), category, vars);
        if (line == null || line.isEmpty())
        {
            log.debug("no host line for category={} host={}", category, hostName());
            return;
        }
        hostSay(line);
    }

    /**
     * Emit a host line: render in the speech bubble overlay (immersive) AND
     * append a styled copy to game chat (reviewable in chat history). Multi-line
     * input (\n-delimited) is collapsed to a single chat line but preserved in
     * the bubble's word-wrap.
     */
    private void hostSay(String line)
    {
        hostSay(line, null);
    }

    /**
     * Same as {@link #hostSay(String)} but fires {@code onInstalled} the moment
     * the line actually becomes the visible overhead text in the speech overlay.
     * Used to gate side effects (banner reveal, sound effects, animations) so
     * they coincide with the host's verbal delivery instead of racing ahead.
     *
     * The callback fires on the overlay's render thread (Swing EDT), so any
     * client-side game-state mutation must be re-routed through
     * {@code clientThread.invoke}.
     */
    private void hostSay(String line, Runnable onInstalled)
    {
        String chatLine = line.replace("\n", " ");
        String formatted = new ChatMessageBuilder()
            .append(ChatColorType.HIGHLIGHT)
            .append(hostName() + ": ")
            .append(ChatColorType.NORMAL)
            .append(chatLine)
            .build();
        client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", formatted, null);
        speechOverlay.say(line, onInstalled);
    }

    /** Repaint the side-panel match view from the current activeMatch snapshot. */
    private void renderActiveMatchPanel()
    {
        MatchSession session = activeMatch;
        if (panel == null) return;
        if (session == null)
        {
            panel.renderMatch(null);
            return;
        }
        String header;
        switch (session.getState())
        {
            case STAGING:
                header = session.isLocalReady()
                    ? "Ready — waiting for opponent"
                    : "Step into the arena around the host";
                break;
            case IN_PROGRESS:
                int qi = session.getCurrentQuestionIndex();
                header = qi >= 0 ? "Round " + (qi + 1) + " of 5" : "Get ready…";
                break;
            case COMPLETE:
            default:
                header = "Match complete";
                break;
        }

        String leftStatus = "";
        String rightStatus = "";
        if (session.getState() == MatchSession.State.IN_PROGRESS
            && session.getLastCorrectDisplay() != null)
        {
            if (session.getLastCorrectDisplay().equalsIgnoreCase(session.myDisplayName))
            {
                leftStatus = "correct";
            }
            else if (session.getLastCorrectDisplay().equalsIgnoreCase(session.opponentDisplayName))
            {
                rightStatus = "correct";
            }
        }

        int leftScore = session.getScores().getOrDefault(session.myDisplayName, 0);
        int rightScore = session.getScores().getOrDefault(session.opponentDisplayName, 0);

        panel.renderMatch(new TriviaPanel.MatchView(
            header,
            session.myDisplayName, leftScore, leftStatus,
            session.opponentDisplayName, rightScore, rightStatus));
    }

    /**
     * Clear the active-match panel a few seconds after completion. We compare
     * matchId so that if a new match has begun in the meantime, we don't
     * clobber it.
     */
    private void scheduleClearActiveMatch(String matchId)
    {
        new java.util.Timer(true).schedule(new java.util.TimerTask()
        {
            @Override
            public void run()
            {
                clientThread.invoke(() ->
                {
                    MatchSession s = activeMatch;
                    if (s != null && matchId.equals(s.matchId))
                    {
                        activeMatch = null;
                        renderActiveMatchPanel();
                    }
                });
            }
            // 7s: lets the full cheer (3s) + wave (1.5s) + walk-out (2s)
            // sequence in scheduleHostExit complete before we clear the panel.
        }, 7_000);
    }

    private static String humanReason(String reason)
    {
        if (reason == null) return "unknown";
        switch (reason)
        {
            case "accepted": return "accepted";
            case "mutual_accept": return "both challenged each other — match starting";
            case "declined": return "declined by target";
            case "expired": return "no response (expired)";
            case "cancelled": return "cancelled";
            case "out_of_range": return "target is too far away";
            case "target_busy": return "target is in another match";
            case "target_refusing": return "target isn't accepting challenges";
            case "target_offline": return "target isn't online";
            default: return reason;
        }
    }

    // -- Helpers -----------------------------------------------------------

    private void startWebsocket()
    {
        Player me = client.getLocalPlayer();
        if (me == null || me.getName() == null)
        {
            return;
        }
        wsClient.updateDisplayName(me.getName());
        wsClient.start(config.backendUrl(), me.getName(), config.acceptingChallenges());
    }

    private void refreshMatchHistory()
    {
        Request req = new Request.Builder().url(config.apiUrl() + "/api/matches?limit=5").build();
        httpClient.newCall(req).enqueue(new Callback()
        {
            @Override
            public void onFailure(Call call, IOException e)
            {
                if (panel != null)
                {
                    panel.renderHistory(List.of());
                }
            }

            @Override
            public void onResponse(Call call, Response response) throws IOException
            {
                try (Response r = response)
                {
                    if (!r.isSuccessful() || r.body() == null)
                    {
                        return;
                    }
                    String body = r.body().string();
                    com.google.gson.JsonArray arr = gson.fromJson(body, com.google.gson.JsonArray.class);
                    List<String> rows = new ArrayList<>();
                    for (JsonElement el : arr)
                    {
                        com.google.gson.JsonObject obj = el.getAsJsonObject();
                        String a = obj.getAsJsonArray("opponents").get(0).getAsString();
                        String b = obj.getAsJsonArray("opponents").get(1).getAsString();
                        String winner = obj.get("winnerDisplayName").isJsonNull() ? null : obj.get("winnerDisplayName").getAsString();
                        rows.add(a + " vs " + b + " — " + (winner == null ? "draw" : winner + " wins"));
                    }
                    if (panel != null)
                    {
                        panel.renderHistory(rows);
                    }
                }
            }
        });
    }

}

package com.runetrivia.match;

import com.runetrivia.net.messages.Domain;
import com.runetrivia.net.messages.Domain.ArenaProposal;
import com.runetrivia.net.messages.Domain.WorldPoint;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.Player;
import net.runelite.api.coords.LocalPoint;

/**
 * Walks outward from the local player looking for a tile that can host the
 * trivia NPC, with two walkable neighbors on opposite sides for the two
 * players. Returns null if no suitable arrangement fits within {@link #MAX_RADIUS}.
 *
 * Everything here runs on the game thread (or with a snapshot of the scene
 * captured on it). The Client is touched only via methods documented as
 * safe outside the game thread (scene + collision data are guarded by
 * RuneLite's API for read-only access).
 */
@Singleton
public class ArenaTileFinder
{
    /** Search no more than this many tiles out (Chebyshev distance). */
    public static final int MAX_RADIUS = 5;

    private static final int BLOCK_FLAGS = CollisionDataFlag.BLOCK_MOVEMENT_FULL
        | CollisionDataFlag.BLOCK_MOVEMENT_OBJECT;

    private final Client client;

    @Inject
    public ArenaTileFinder(Client client)
    {
        this.client = client;
    }

    /**
     * Find a usable arena around the local player. Returns null if the
     * player isn't loaded or no suitable tile arrangement exists nearby.
     */
    public ArenaProposal findArena()
    {
        Player me = client.getLocalPlayer();
        if (me == null)
        {
            return null;
        }
        net.runelite.api.coords.WorldPoint anchorWp = me.getWorldLocation();
        if (anchorWp == null)
        {
            return null;
        }
        LocalPoint anchorLp = LocalPoint.fromWorld(client, anchorWp);
        if (anchorLp == null)
        {
            return null;
        }

        int plane = client.getPlane();
        CollisionData[] maps = client.getCollisionMaps();
        if (maps == null || maps.length <= plane || maps[plane] == null)
        {
            return null;
        }
        int[][] flags = maps[plane].getFlags();

        int sx = anchorLp.getSceneX();
        int sy = anchorLp.getSceneY();

        // Spiral outward at radius r (Chebyshev). Order: closer first.
        for (int r = 1; r <= MAX_RADIUS; r++)
        {
            for (int dx = -r; dx <= r; dx++)
            {
                for (int dy = -r; dy <= r; dy++)
                {
                    if (Math.max(Math.abs(dx), Math.abs(dy)) != r)
                    {
                        continue; // only the ring at distance r
                    }
                    int tx = sx + dx;
                    int ty = sy + dy;
                    if (!inBounds(flags, tx, ty) || !walkable(flags, tx, ty))
                    {
                        continue;
                    }
                    Pair pair = findOppositeNeighbors(flags, tx, ty);
                    if (pair == null)
                    {
                        continue;
                    }
                    return buildProposal(plane, tx, ty, pair, anchorWp);
                }
            }
        }
        return null;
    }

    private boolean walkable(int[][] flags, int sx, int sy)
    {
        return (flags[sx][sy] & BLOCK_FLAGS) == 0;
    }

    private boolean inBounds(int[][] flags, int sx, int sy)
    {
        return sx >= 0 && sy >= 0 && sx < flags.length && flags[sx].length > sy;
    }

    private Pair findOppositeNeighbors(int[][] flags, int sx, int sy)
    {
        // East+West preferred, then North+South.
        if (inBounds(flags, sx - 1, sy) && inBounds(flags, sx + 1, sy)
            && walkable(flags, sx - 1, sy) && walkable(flags, sx + 1, sy))
        {
            return new Pair(-1, 0, 1, 0);
        }
        if (inBounds(flags, sx, sy - 1) && inBounds(flags, sx, sy + 1)
            && walkable(flags, sx, sy - 1) && walkable(flags, sx, sy + 1))
        {
            return new Pair(0, -1, 0, 1);
        }
        return null;
    }

    private ArenaProposal buildProposal(int plane, int sx, int sy, Pair p, net.runelite.api.coords.WorldPoint anchorWp)
    {
        int baseX = anchorWp.getX() - (LocalPoint.fromWorld(client, anchorWp)).getSceneX();
        int baseY = anchorWp.getY() - (LocalPoint.fromWorld(client, anchorWp)).getSceneY();

        WorldPoint npcTile = new WorldPoint(baseX + sx, baseY + sy, plane);
        WorldPoint challengerTile = new WorldPoint(baseX + sx + p.dxA, baseY + sy + p.dyA, plane);
        WorldPoint challengedTile = new WorldPoint(baseX + sx + p.dxB, baseY + sy + p.dyB, plane);

        ArenaProposal arena = new ArenaProposal();
        arena.regionId = anchorWp.getRegionID();
        arena.npcTile = npcTile;
        arena.challengerTile = challengerTile;
        arena.challengedTile = challengedTile;
        return arena;
    }

    /** WorldPoint wrapper for the challenger's current location, for inclusion in the wire payload. */
    public WorldPoint currentLocation()
    {
        Player me = client.getLocalPlayer();
        if (me == null || me.getWorldLocation() == null)
        {
            return null;
        }
        net.runelite.api.coords.WorldPoint wp = me.getWorldLocation();
        return new WorldPoint(wp.getX(), wp.getY(), wp.getPlane());
    }

    private static final class Pair
    {
        final int dxA;
        final int dyA;
        final int dxB;
        final int dyB;

        Pair(int dxA, int dyA, int dxB, int dyB)
        {
            this.dxA = dxA;
            this.dyA = dyA;
            this.dxB = dxB;
            this.dyB = dyB;
        }
    }
}

package com.runetrivia.match;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.ThreadLocalRandom;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;

/**
 * Loads per-NPC dialogue lines from classpath resources under
 * {@code /host_lines/}. See {@code host_lines/README.md} for the schema.
 *
 * Override files are partial — any missing category falls back to
 * {@code _default.json}. Per-NPC files are loaded lazily on first lookup
 * and cached for the lifetime of the plugin process.
 */
@Singleton
@Slf4j
public class HostLines
{
    private static final String RESOURCE_ROOT = "/host_lines/";
    private static final String DEFAULTS_FILE = "_default.json";

    /** category -> lines, populated from _default.json on construction. */
    private final Map<String, List<String>> defaults = new HashMap<>();
    /** slug -> category -> lines. Populated lazily on first lookup per slug. */
    private final Map<String, Map<String, List<String>>> overrides = new HashMap<>();
    /** Scalar int fields from _default.json (e.g. "idleAnimation"). */
    private final Map<String, Integer> defaultInts = new HashMap<>();
    /** slug -> int fields. Lazily loaded same as line overrides. */
    private final Map<String, Map<String, Integer>> overrideInts = new HashMap<>();
    /** Slugs that we've already attempted to load (success or miss) — never retry. */
    private final Map<String, Boolean> attempted = new HashMap<>();

    private final Gson gson;

    @Inject
    public HostLines(Gson gson)
    {
        this.gson = gson;
        loadDefaults();
    }

    /**
     * Convert a display name into the slug used for the JSON filename:
     * lowercase + any non-[a-z0-9] run replaced with a single '_'.
     * E.g. "King Roald" -> "king_roald".
     */
    public static String slugFor(String displayName)
    {
        if (displayName == null) return "_default";
        String s = displayName.toLowerCase().replaceAll("[^a-z0-9]+", "_");
        // Trim leading/trailing underscores that the replace may have introduced.
        return s.replaceAll("^_+|_+$", "");
    }

    /**
     * Pick a random line from the given category for the given host, applying
     * {placeholder} substitutions. Returns null if the category has no lines
     * (which shouldn't happen if _default.json is intact, but defends against
     * editing accidents).
     */
    public String pick(String displayName, String category, Map<String, String> interpolations)
    {
        List<String> lines = linesFor(displayName, category);
        if (lines == null || lines.isEmpty()) return null;
        String chosen = lines.get(ThreadLocalRandom.current().nextInt(lines.size()));
        return interpolate(chosen, interpolations);
    }

    private List<String> linesFor(String displayName, String category)
    {
        String slug = slugFor(displayName);
        Map<String, List<String>> over = loadOverride(slug);
        if (over != null)
        {
            List<String> custom = over.get(category);
            if (custom != null && !custom.isEmpty()) return custom;
        }
        return defaults.get(category);
    }

    /**
     * Look up a scalar integer config value for the given host. Per-NPC
     * overrides win; falls back to the value in {@code _default.json} if
     * present; otherwise returns {@code fallback}.
     *
     * Used for things like {@code idleAnimation} where each NPC may want
     * a different value (Reldo reads a book, King Roald sits, etc.).
     */
    public int getInt(String displayName, String key, int fallback)
    {
        String slug = slugFor(displayName);
        // Trigger a load of the override file so overrideInts is populated.
        loadOverride(slug);
        Map<String, Integer> over = overrideInts.get(slug);
        if (over != null && over.containsKey(key)) return over.get(key);
        Integer def = defaultInts.get(key);
        return def != null ? def : fallback;
    }

    private Map<String, List<String>> loadOverride(String slug)
    {
        Map<String, List<String>> cached = overrides.get(slug);
        if (cached != null) return cached;
        if (attempted.containsKey(slug)) return null;
        attempted.put(slug, true);
        Map<String, Integer> intsOut = new HashMap<>();
        Map<String, List<String>> loaded = loadJson(slug + ".json", intsOut);
        if (loaded != null) overrides.put(slug, loaded);
        if (!intsOut.isEmpty()) overrideInts.put(slug, intsOut);
        return loaded;
    }

    private void loadDefaults()
    {
        Map<String, List<String>> def = loadJson(DEFAULTS_FILE, defaultInts);
        if (def == null)
        {
            log.warn("host_lines/_default.json missing — bubble will be silent for unhandled categories");
            return;
        }
        defaults.putAll(def);
    }

    /**
     * Parse a host-config JSON file. Categories whose value is an array of
     * strings are treated as line categories (returned via the return value).
     * Categories whose value is a number are written into {@code intsOut}
     * (for things like {@code "idleAnimation": 847}). Other shapes — strings,
     * objects, the {@code _doc} comment — are ignored.
     *
     * Returns null if the file is not on the classpath.
     */
    private Map<String, List<String>> loadJson(String filename, Map<String, Integer> intsOut)
    {
        String path = RESOURCE_ROOT + filename;
        try (InputStream is = HostLines.class.getResourceAsStream(path))
        {
            if (is == null) return null;
            JsonObject root = gson.fromJson(new InputStreamReader(is, StandardCharsets.UTF_8), JsonObject.class);
            if (root == null) return Collections.emptyMap();
            Map<String, List<String>> out = new HashMap<>();
            for (Map.Entry<String, JsonElement> entry : root.entrySet())
            {
                JsonElement v = entry.getValue();
                if (v == null) continue;
                if (v.isJsonArray())
                {
                    List<String> lines = new ArrayList<>();
                    v.getAsJsonArray().forEach(el ->
                    {
                        if (el != null && el.isJsonPrimitive()) lines.add(el.getAsString());
                    });
                    if (!lines.isEmpty()) out.put(entry.getKey(), lines);
                }
                else if (v.isJsonPrimitive() && v.getAsJsonPrimitive().isNumber())
                {
                    try { intsOut.put(entry.getKey(), v.getAsInt()); }
                    catch (NumberFormatException ignored) { /* malformed number */ }
                }
            }
            return out;
        }
        catch (IOException e)
        {
            log.warn("failed reading {}: {}", path, e.toString());
            return null;
        }
        catch (Exception e)
        {
            log.warn("failed parsing {}: {}", path, e.toString());
            return null;
        }
    }

    /** Replace {key} tokens with values from the map. Unknown tokens are left as-is. */
    static String interpolate(String template, Map<String, String> values)
    {
        if (values == null || values.isEmpty()) return template;
        String out = template;
        for (Map.Entry<String, String> e : values.entrySet())
        {
            String token = "{" + e.getKey() + "}";
            // String.replace handles overlapping correctly and is fine for our scale.
            out = out.replace(token, e.getValue() == null ? "" : e.getValue());
        }
        return out;
    }
}

package com.runetrivia.match;

import com.runetrivia.net.messages.Domain;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Animation;
import net.runelite.api.Client;
import net.runelite.api.Model;
import net.runelite.api.ModelData;
import net.runelite.api.NPCComposition;
import net.runelite.api.Player;
import net.runelite.api.RuneLiteObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.callback.ClientThread;

/**
 * Spawns the trivia host as a {@link RuneLiteObject} with the real OSRS
 * NPC model, applies the NPC's recolors, and positions it at the assigned
 * tile.
 *
 * <h3>Model-loading dance</h3>
 *
 * {@link Client#loadModelData(int)} returns null when the model file is not
 * yet in the cache (RuneLite loads assets lazily). We therefore can't
 * guarantee a successful spawn on the first attempt. The renderer retains
 * the "want to spawn" intent in {@link #pendingNpcId} / {@link #pendingTile}
 * and {@link #onTick()} re-attempts every GameTick until all parts have
 * loaded.
 *
 * <h3>Threading</h3>
 *
 * Everything that touches the {@link Client} API runs on the game thread.
 * Public methods marshal through {@link ClientThread#invoke}. Internal
 * methods assume they're already on the right thread.
 */
@Singleton
@Slf4j
public class HostNpcRenderer
{
    /** Default idle animation: generic human standing pose. Override per-NPC if it looks wrong. */
    public static final int DEFAULT_IDLE_ANIM = 808;
    /** Standard human walk animation. Suitable for most humanoid NPC skeletons. */
    public static final int DEFAULT_WALK_ANIM = 819;
    /** South-facing — used only until {@link #updateOrientation()} starts tracking the player. */
    private static final int INITIAL_ORIENTATION = 0;
    /** Per-tick orientation step (JagEx units). 256 = ~45° per tick → ~4 ticks for a 180° turn. */
    private static final int ORIENTATION_STEP = 256;

    private final Client client;
    private final ClientThread clientThread;

    // -- Intent (touched only on the client thread) -----------------------
    private int pendingNpcId = -1;
    private Domain.WorldPoint pendingTile;
    private RuneLiteObject obj;
    private boolean spawned;

    // -- Animation state --------------------------------------------------
    private int idleAnimId = DEFAULT_IDLE_ANIM;
    /** Wall-clock ms when the current one-shot reaction should revert to idle. 0 = no active reaction. */
    private long reactionEndsAt = 0;
    /** Whether the looping idle animation is currently applied. Falsey -> retry next tick. */
    private boolean idleApplied = false;
    /** Current rendered orientation, smoothed via ORIENTATION_STEP per tick. */
    private int currentOrient = INITIAL_ORIENTATION;

    // -- Walk state -------------------------------------------------------
    /**
     * Walking is modelled the same way OSRS does it: each segment is one
     * tile that takes one game tick (~600ms) to traverse. The model
     * interpolates linearly *within* a segment, then snaps to the segment
     * end on the next GameTick and re-targets the following tile. This is
     * what keeps the leg-step animation locked to the body's motion —
     * without segment-paced movement the model gait-cycles independently
     * of position and the eye reads it as gliding/ice-skating.
     */
    /** Approx OSRS game-tick duration; matches the cadence of the GameTick event. */
    private static final long TICK_MS = 600;
    private boolean walking = false;
    /** Final destination tile (snapshot of caller intent). */
    private Domain.WorldPoint walkEndTile;
    /** Current segment endpoints (one tile apart). Null when not walking. */
    private Domain.WorldPoint walkSegmentStart;
    private Domain.WorldPoint walkSegmentEnd;
    /** Wall-clock start of the current segment. Resets on each GameTick advance. */
    private long walkSegmentStartedAt;
    /** Animation used during the walk. Per-NPC override possible later. */
    private int walkAnimId = DEFAULT_WALK_ANIM;
    /** Optional callback run on the client thread once the host arrives at walkEndTile. */
    private Runnable walkCompletionCallback;
    /**
     * A walk that has been requested but hasn't started yet — waiting for
     * the next GameTick to align segment timing with the game's tick clock.
     * Without this alignment, segments and GameTicks drift independently
     * and the host either skips forward (segment commits early) or stutters
     * (segment finishes early and waits).
     */
    private Domain.WorldPoint pendingWalkTarget;
    private Runnable pendingWalkCallback;

    /**
     * Callbacks queued via {@link #whenArrived(Runnable)} — run in FIFO order
     * once the host finishes its current/pending walk. Used by the plugin to
     * defer host speech that the server might emit before the walk-in
     * finishes (e.g. MATCH_STARTED's "get ready" line, which arrives ~1s
     * into a ~3s walk-in).
     */
    private final java.util.ArrayDeque<Runnable> arrivalCallbacks = new java.util.ArrayDeque<>();

    @Inject
    public HostNpcRenderer(Client client, ClientThread clientThread)
    {
        this.client = client;
        this.clientThread = clientThread;
    }

    /**
     * Ask the renderer to spawn the given NPC at the given tile. Idempotent —
     * calling with the same args while already spawned is a no-op; calling
     * with different args despawns the current object first.
     */
    public void requestSpawn(int npcId, Domain.WorldPoint tile)
    {
        if (npcId <= 0 || tile == null) return;
        clientThread.invoke(() ->
        {
            if (spawned && npcId == pendingNpcId && tile.equals(pendingTile))
            {
                return;
            }
            despawnInternal();
            pendingNpcId = npcId;
            pendingTile = tile;
            spawned = false;
            trySpawn();
        });
    }

    /** Despawn whatever's currently shown. Idempotent. */
    public void requestDespawn()
    {
        clientThread.invoke(() ->
        {
            despawnInternal();
            pendingNpcId = -1;
            pendingTile = null;
        });
    }

    /**
     * Override the looping idle animation. Defaults to {@link #DEFAULT_IDLE_ANIM}
     * (generic human standing). Useful for non-humanoid NPCs whose default
     * skeleton doesn't match the human bind pose.
     */
    public void setIdleAnimation(int animId)
    {
        clientThread.invoke(() ->
        {
            this.idleAnimId = animId;
            if (spawned && reactionEndsAt == 0)
            {
                applyAnimation(animId, true);
            }
        });
    }

    /**
     * Walk from the current position to {@code target}, one tile per game
     * tick. The total walk duration is implicitly {@code chebyshev(start,
     * target) * TICK_MS}. The {@code durationMs} parameter is retained for
     * caller compatibility but ignored — OSRS movement is tile-paced, not
     * duration-paced, and forcing a different speed is what made the walk
     * look like ice-skating.
     *
     * While walking:
     *   * the walk animation plays (looping);
     *   * each GameTick (~600ms) the segment advances by one tile;
     *   * within each segment, position is linearly interpolated per
     *     ClientTick so the model glides smoothly between tile centers
     *     in sync with the step animation;
     *   * on arrival, position snaps to the destination tile and the host
     *     reverts to idle.
     */
    public void walkTo(Domain.WorldPoint target, long durationMs)
    {
        walkTo(target, (Runnable) null);
    }

    /**
     * Same as {@link #walkTo(Domain.WorldPoint, long)} but with a callback
     * fired on the client thread the moment the host arrives at the
     * destination. Cleaner than scheduling separate Timers that race the
     * walk's actual completion.
     */
    public void walkTo(Domain.WorldPoint target, Runnable onArrived)
    {
        if (target == null) return;
        clientThread.invoke(() ->
        {
            if (!spawned || obj == null) return;
            // Queue the walk to start on the next GameTick. Starting at an
            // arbitrary wall-clock time would make segments drift relative
            // to the GameTick clock, which is how the moonwalk / stutter
            // bugs we hit earlier manifested. The cost is up to ~600ms
            // delay before walking visibly starts — same delay OSRS itself
            // has between click-to-move and the first step.
            pendingWalkTarget = target;
            pendingWalkCallback = onArrived;
        });
    }

    /**
     * Run {@code r} on the client thread once the host has finished any
     * in-progress or pending walk. Fires immediately if no walk is active.
     * Multiple callbacks run in FIFO order.
     *
     * Used to keep host speech (e.g. the "get ready" line emitted by the
     * server's MATCH_STARTED frame) from appearing while the host is still
     * mid-stride during the walk-in.
     */
    public void whenArrived(Runnable r)
    {
        if (r == null) return;
        clientThread.invoke(() ->
        {
            if (!walking && pendingWalkTarget == null)
            {
                r.run();
                return;
            }
            arrivalCallbacks.add(r);
        });
    }

    /** Drain queued arrival callbacks. Caller must already be on client thread. */
    private void fireArrivalCallbacks()
    {
        while (!arrivalCallbacks.isEmpty())
        {
            Runnable r = arrivalCallbacks.poll();
            try { r.run(); }
            catch (Exception e) { log.warn("arrival callback threw: {}", e.toString()); }
        }
    }

    /** One-tile step from {@code from} toward {@code to}. Returns null if already there. */
    private static Domain.WorldPoint nextTileToward(Domain.WorldPoint from, Domain.WorldPoint to)
    {
        if (from == null || to == null) return null;
        int dx = Integer.signum(to.x - from.x);
        int dy = Integer.signum(to.y - from.y);
        if (dx == 0 && dy == 0) return null;
        return new Domain.WorldPoint(from.x + dx, from.y + dy, from.plane);
    }

    /** Override the walk animation. Defaults to {@link #DEFAULT_WALK_ANIM}. */
    public void setWalkAnimation(int animId)
    {
        clientThread.invoke(() -> this.walkAnimId = animId);
    }

    /**
     * Per-client-tick callback (~20ms). Used for smooth position interpolation
     * during walks — much finer-grained than the 600ms GameTick. Called from
     * the plugin's ClientTick subscriber.
     */
    public void onClientTick()
    {
        if (!spawned || obj == null || !walking) return;
        if (walkSegmentStart == null || walkSegmentEnd == null) return;

        // Linear interpolation across the current segment. Linear (not cosine
        // ease) matches how the real game animates a unit between tile
        // centers within a tick — a constant-velocity step in sync with the
        // gait animation. Easing would re-introduce the moonwalk feel.
        long elapsed = System.currentTimeMillis() - walkSegmentStartedAt;
        double t = Math.min(1.0, elapsed / (double) TICK_MS);

        WorldPoint startWorld = new WorldPoint(walkSegmentStart.x, walkSegmentStart.y, walkSegmentStart.plane);
        WorldPoint endWorld = new WorldPoint(walkSegmentEnd.x, walkSegmentEnd.y, walkSegmentEnd.plane);
        LocalPoint startLp = LocalPoint.fromWorld(client, startWorld);
        LocalPoint endLp = LocalPoint.fromWorld(client, endWorld);
        if (startLp == null || endLp == null) return;
        int lx = (int) Math.round(startLp.getX() + (endLp.getX() - startLp.getX()) * t);
        int ly = (int) Math.round(startLp.getY() + (endLp.getY() - startLp.getY()) * t);
        obj.setLocation(new LocalPoint(lx, ly), walkSegmentEnd.plane);

        // Face the direction of travel — keep the orientation snapped to
        // the segment's direction so the model faces forward as it walks.
        int dx = walkSegmentEnd.x - walkSegmentStart.x;
        int dy = walkSegmentEnd.y - walkSegmentStart.y;
        if (dx != 0 || dy != 0)
        {
            int target = ((int) (Math.atan2(-dx, -dy) * 1024 / Math.PI)) & 0x7FF;
            currentOrient = target;
            obj.setOrientation(currentOrient);
        }
    }

    /**
     * Play a reaction animation for the given duration, then revert to idle.
     *
     * Implementation detail: we set the reaction to loop (shouldLoop=true)
     * for the entire duration. {@code RuneLiteObject} stops rendering its
     * model the moment a non-looping animation completes — which would
     * make the host disappear mid-reaction. Looping the reaction keeps the
     * model visible; the timer-based revert swaps back to idle when the
     * duration elapses.
     */
    public void playReaction(int animId, long durationMs)
    {
        clientThread.invoke(() ->
        {
            if (!spawned) return;
            if (!applyAnimation(animId, true)) return;
            reactionEndsAt = System.currentTimeMillis() + Math.max(0, durationMs);
        });
    }

    /**
     * Called from the plugin's GameTick handler. Handles:
     *   * retrying the spawn until model parts have loaded;
     *   * reverting one-shot reactions back to idle when their duration elapses;
     *   * smoothly rotating to face the local player.
     */
    public void onTick()
    {
        if (!spawned)
        {
            if (pendingNpcId > 0 && pendingTile != null) trySpawn();
            return;
        }

        // Start a queued walk now (at this GameTick boundary). All segments
        // begin and end on GameTicks so interpolation completes cleanly
        // each tick.
        if (pendingWalkTarget != null && !walking)
        {
            startPendingWalk();
            // Return immediately — the first segment was just initialized
            // with walkSegmentStartedAt=now. Falling through to
            // advanceWalkSegment in the same tick would commit and discard
            // segment 1 before any ClientTick gets to render it, producing
            // a one-tile teleport on the first step. The first segment
            // gets its full TICK_MS only if we wait for the *next* GameTick
            // to advance.
            if (walking) return;
        }

        if (walking)
        {
            advanceWalkSegment();
            return;
        }

        // Reaction expired -> back to idle loop.
        if (reactionEndsAt > 0 && System.currentTimeMillis() >= reactionEndsAt)
        {
            reactionEndsAt = 0;
            idleApplied = false; // force reapply below
        }
        // If we're not mid-reaction and the idle isn't currently applied
        // (typically because the animation cache was cold at spawn time),
        // keep retrying every tick until it sticks.
        if (reactionEndsAt == 0 && !idleApplied)
        {
            idleApplied = applyAnimation(idleAnimId, true);
        }
        updateOrientation();
    }

    /**
     * Activate a pending walk. Called from {@link #onTick} so segment timing
     * is anchored to GameTicks. Switches to the walk animation and sets up
     * the first one-tile segment, which will complete by the next GameTick.
     */
    private void startPendingWalk()
    {
        walkEndTile = pendingWalkTarget;
        walkCompletionCallback = pendingWalkCallback;
        pendingWalkTarget = null;
        pendingWalkCallback = null;

        walkSegmentStart = pendingTile;
        walkSegmentEnd = nextTileToward(pendingTile, walkEndTile);
        walkSegmentStartedAt = System.currentTimeMillis();
        walking = walkSegmentEnd != null;

        if (walking)
        {
            applyAnimation(walkAnimId, true);
            idleApplied = false;
            reactionEndsAt = 0;
        }
        else
        {
            // Already at the target — fire callback immediately.
            if (walkCompletionCallback != null)
            {
                Runnable cb = walkCompletionCallback;
                walkCompletionCallback = null;
                cb.run();
            }
            // Any whenArrived() queue also drains here, since we never had
            // a walk to wait for in the first place.
            fireArrivalCallbacks();
        }
    }

    /**
     * One-tile step per GameTick. Because every segment begins at a
     * GameTick (see {@link #startPendingWalk}) and GameTicks fire every
     * ~TICK_MS, the interpolation in {@link #onClientTick} naturally
     * reaches t=1.0 by the time we get here — no need to gate on elapsed.
     */
    private void advanceWalkSegment()
    {
        if (walkSegmentEnd == null) return;

        pendingTile = walkSegmentEnd;
        // Reached the final destination?
        if (walkSegmentEnd.x == walkEndTile.x && walkSegmentEnd.y == walkEndTile.y)
        {
            WorldPoint world = new WorldPoint(walkEndTile.x, walkEndTile.y, walkEndTile.plane);
            LocalPoint lp = LocalPoint.fromWorld(client, world);
            if (lp != null) obj.setLocation(lp, walkEndTile.plane);
            walking = false;
            walkSegmentStart = null;
            walkSegmentEnd = null;
            idleApplied = applyAnimation(idleAnimId, true);
            // Fire arrival callback on the client thread.
            Runnable cb = walkCompletionCallback;
            walkCompletionCallback = null;
            if (cb != null) cb.run();
            // Drain any whenArrived() queue — deferred speech etc.
            fireArrivalCallbacks();
            return;
        }
        // Set up the next one-tile segment.
        walkSegmentStart = walkSegmentEnd;
        walkSegmentEnd = nextTileToward(walkSegmentStart, walkEndTile);
        walkSegmentStartedAt = System.currentTimeMillis();
    }

    // -- internal ---------------------------------------------------------

    private void trySpawn()
    {
        if (pendingNpcId <= 0 || pendingTile == null) return;

        NPCComposition comp = client.getNpcDefinition(pendingNpcId);
        if (comp == null)
        {
            // Composition may itself be lazy-loaded; try again next tick.
            return;
        }
        int[] modelIds = comp.getModels();
        if (modelIds == null || modelIds.length == 0)
        {
            log.warn("NPC {} has no models", pendingNpcId);
            cancel();
            return;
        }

        ModelData[] parts = new ModelData[modelIds.length];
        for (int i = 0; i < modelIds.length; i++)
        {
            parts[i] = client.loadModelData(modelIds[i]);
            if (parts[i] == null)
            {
                // At least one part not cached yet — retry next tick.
                return;
            }
        }

        ModelData merged = parts.length == 1 ? parts[0] : client.mergeModels(parts);
        if (merged == null)
        {
            log.warn("mergeModels returned null for npc {}", pendingNpcId);
            cancel();
            return;
        }

        // Apply NPC recolors (so e.g. King Roald isn't wearing the base palette).
        short[] origColors = comp.getColorToReplace();
        short[] newColors = comp.getColorToReplaceWith();
        if (origColors != null && newColors != null && origColors.length > 0)
        {
            merged.cloneColors();
            int n = Math.min(origColors.length, newColors.length);
            for (int i = 0; i < n; i++)
            {
                merged.recolor(origColors[i], newColors[i]);
            }
        }

        Model model;
        try
        {
            model = merged.light();
        }
        catch (Exception e)
        {
            log.warn("lighting model failed for npc {}: {}", pendingNpcId, e.toString());
            cancel();
            return;
        }
        if (model == null)
        {
            log.warn("light() returned null for npc {}", pendingNpcId);
            cancel();
            return;
        }

        WorldPoint world = new WorldPoint(pendingTile.x, pendingTile.y, pendingTile.plane);
        LocalPoint lp = LocalPoint.fromWorld(client, world);
        if (lp == null)
        {
            // Tile outside the loaded scene — try again next tick (player may
            // still be walking into the region).
            return;
        }

        RuneLiteObject newObj = client.createRuneLiteObject();
        newObj.setModel(model);
        this.currentOrient = INITIAL_ORIENTATION;
        newObj.setOrientation(currentOrient);
        newObj.setLocation(lp, pendingTile.plane);
        newObj.setActive(true);

        this.obj = newObj;
        this.spawned = true;
        // Kick off the idle loop immediately so the NPC isn't frozen in the
        // bind pose. If the animation is cold-cached this returns false;
        // onTick keeps retrying every tick until it succeeds.
        this.idleApplied = applyAnimation(idleAnimId, true);
        log.info("spawned host NPC id={} ({}) at ({}, {}, plane {}); idleApplied={}",
            pendingNpcId, comp.getName(), pendingTile.x, pendingTile.y, pendingTile.plane, idleApplied);
    }

    /**
     * Set the RuneLiteObject's current animation to the given id, looping
     * or one-shot. Returns true if applied, false if the animation wasn't
     * available (cache miss — caller may want to retry later).
     */
    private boolean applyAnimation(int animId, boolean loop)
    {
        if (obj == null || animId <= 0) return false;
        Animation anim = client.loadAnimation(animId);
        if (anim == null) return false;
        obj.setAnimation(anim);
        obj.setShouldLoop(loop);
        return true;
    }

    /**
     * Smoothly rotate the host to face the local player. JagEx orientation
     * units are 0..2047, where 0=south, 512=west, 1024=north, 1536=east.
     *
     * The formula {@code atan2(-dx, -dy)} maps the world-space delta from
     * NPC to player into that convention; we then advance currentOrient
     * toward the target by at most ORIENTATION_STEP per tick (so the
     * NPC doesn't snap-rotate jarringly).
     */
    private void updateOrientation()
    {
        if (obj == null || pendingTile == null) return;
        Player me = client.getLocalPlayer();
        if (me == null) return;
        WorldPoint myWp = me.getWorldLocation();
        if (myWp == null) return;
        if (myWp.getPlane() != pendingTile.plane) return;
        int dx = myWp.getX() - pendingTile.x;
        int dy = myWp.getY() - pendingTile.y;
        if (dx == 0 && dy == 0) return; // player on the host tile — keep facing where we were

        int target = ((int) (Math.atan2(-dx, -dy) * 1024 / Math.PI)) & 0x7FF;
        int diff = ((target - currentOrient + 1024 + 2048) % 2048) - 1024;
        if (Math.abs(diff) <= ORIENTATION_STEP)
        {
            currentOrient = target;
        }
        else
        {
            currentOrient = ((currentOrient + (diff > 0 ? ORIENTATION_STEP : -ORIENTATION_STEP)) + 2048) % 2048;
        }
        obj.setOrientation(currentOrient);
    }

    private void despawnInternal()
    {
        if (obj != null)
        {
            try
            {
                obj.setActive(false);
            }
            catch (Exception e)
            {
                log.warn("despawn setActive(false) threw: {}", e.toString());
            }
            obj = null;
        }
        spawned = false;
        reactionEndsAt = 0;
        idleApplied = false;
        currentOrient = INITIAL_ORIENTATION;
        walking = false;
        walkSegmentStart = null;
        walkSegmentEnd = null;
        walkEndTile = null;
        walkCompletionCallback = null;
        pendingWalkTarget = null;
        pendingWalkCallback = null;
        arrivalCallbacks.clear();
    }

    /** Permanent failure: drop the request so we stop retrying every tick. */
    private void cancel()
    {
        pendingNpcId = -1;
        pendingTile = null;
        despawnInternal();
    }
}

package com.runetrivia.match;

import com.runetrivia.net.messages.Domain.HostNpc;
import com.runetrivia.net.messages.Domain.PerPlayerQuestionResult;
import com.runetrivia.net.messages.Domain.WorldPoint;
import com.runetrivia.util.NameUtil;
import java.util.HashMap;
import java.util.Map;

/**
 * Local plugin-side view of an active match. Owned by the plugin core;
 * mutated only from the game/client thread. Read-only snapshots can be
 * passed to UI components.
 *
 * Lifecycle:
 *   ARENA_STAGED          -> new MatchSession(STAGING)
 *   PLAYER_READY (local)  -> session.localReady = true
 *   MATCH_STARTED         -> state = IN_PROGRESS, scores populated
 *   QUESTION_DELIVERED    -> setCurrentQuestion(...)
 *   QUESTION_RESOLVED     -> applyResolution(...)
 *   MATCH_COMPLETED       -> state = COMPLETE
 *   (or MATCH_FORFEIT/CHALLENGE_RESOLVED if cancelled)
 */
public final class MatchSession
{
    public enum State { STAGING, IN_PROGRESS, COMPLETE }

    /**
     * Chebyshev distance from the host tile that defines the "ready" arena.
     * 2 tiles = 5x5 area (25 tiles), generous enough that pathing into the
     * radius is forgiving without making the arena feel huge.
     */
    public static final int ARENA_RADIUS = 2;

    /** Match id from the server. */
    public final String matchId;
    /** The OSRS region that bounds this match. */
    public final int regionId;
    /** Host NPC the server picked. */
    public final HostNpc host;
    /** Local player's display name (as known by the server). */
    public final String myDisplayName;
    /** Opponent's display name. */
    public final String opponentDisplayName;
    /** Normalized form of {@link #myDisplayName} (matches server keys). */
    public final String myNormalized;
    /** Normalized form of {@link #opponentDisplayName}. */
    public final String opponentNormalized;
    /** Tile we should stand on during staging. */
    public final WorldPoint myAssignedTile;
    /** Tile opponent should stand on. */
    public final WorldPoint opponentAssignedTile;
    /** Original staging deadline (epoch ms). */
    public final long stagingDeadline;

    private State state;
    private boolean localReady;
    /** Running scores keyed by display name. Populated by MATCH_STARTED. */
    private final Map<String, Integer> scores = new HashMap<>();

    /** Number of consecutive ticks the local player's region has differed from the arena region. */
    private int outOfRegionTicks = 0;
    private int currentQuestionIndex = -1;
    private String currentPrompt;
    private long currentDeadline;
    /**
     * Becomes true between QUESTION_RESOLVED for question N and
     * QUESTION_DELIVERED for question N+1 (or MATCH_COMPLETED).
     * While true, chat input is not forwarded as an answer.
     */
    private boolean questionResolved = true;
    /** Display name of whoever got the most recent question right (null = nobody). */
    private String lastCorrectDisplay;
    /** Canonical answer of the most recent question (for UI/overhead). */
    private String lastCanonicalAnswer;

    private MatchSession(
        String matchId,
        int regionId,
        HostNpc host,
        String myDisplayName,
        String opponentDisplayName,
        WorldPoint myAssignedTile,
        WorldPoint opponentAssignedTile,
        long stagingDeadline)
    {
        this.matchId = matchId;
        this.regionId = regionId;
        this.host = host;
        this.myDisplayName = myDisplayName;
        this.opponentDisplayName = opponentDisplayName;
        this.myNormalized = NameUtil.normalize(myDisplayName);
        this.opponentNormalized = NameUtil.normalize(opponentDisplayName);
        this.myAssignedTile = myAssignedTile;
        this.opponentAssignedTile = opponentAssignedTile;
        this.stagingDeadline = stagingDeadline;
        this.state = State.STAGING;
        this.scores.put(myDisplayName, 0);
        this.scores.put(opponentDisplayName, 0);
    }

    /**
     * Map a wire-payload key (which may be normalized OR display-name)
     * back to one of our two display-name keys. Returns null if neither
     * matches (shouldn't happen — defends against server drift).
     */
    private String resolveDisplayName(String wireKey)
    {
        if (wireKey == null) return null;
        if (wireKey.equals(myDisplayName) || wireKey.equals(opponentDisplayName)) return wireKey;
        String n = NameUtil.normalize(wireKey);
        if (n.equals(myNormalized)) return myDisplayName;
        if (n.equals(opponentNormalized)) return opponentDisplayName;
        return null;
    }

    /**
     * Build a session from an ARENA_STAGED payload. Returns null if the
     * local player's display name isn't one of the keys in `tiles` (which
     * would mean the server staged a match for someone else and we got
     * crosstalk — shouldn't happen, but defend).
     */
    public static MatchSession fromArenaStaged(
        String matchId,
        int regionId,
        HostNpc host,
        Map<String, WorldPoint> tiles,
        long stagingDeadline,
        String myDisplayName)
    {
        if (tiles == null || myDisplayName == null) return null;
        // Case-insensitive lookup: the server may have echoed slightly different casing.
        String myKey = null;
        String otherKey = null;
        for (String k : tiles.keySet())
        {
            if (k.equalsIgnoreCase(myDisplayName))
            {
                myKey = k;
            }
            else
            {
                otherKey = k;
            }
        }
        if (myKey == null || otherKey == null) return null;
        return new MatchSession(
            matchId, regionId, host,
            myKey, otherKey,
            tiles.get(myKey), tiles.get(otherKey),
            stagingDeadline);
    }

    // -- State accessors --------------------------------------------------

    public State getState() { return state; }
    public boolean isLocalReady() { return localReady; }
    public Map<String, Integer> getScores() { return scores; }
    public int getCurrentQuestionIndex() { return currentQuestionIndex; }
    public String getCurrentPrompt() { return currentPrompt; }
    public long getCurrentDeadline() { return currentDeadline; }
    public boolean isQuestionActive() { return !questionResolved && state == State.IN_PROGRESS; }
    public String getLastCorrectDisplay() { return lastCorrectDisplay; }
    public String getLastCanonicalAnswer() { return lastCanonicalAnswer; }

    // -- Mutators (called from the plugin core on the client thread) ------

    public void markLocalReady() { this.localReady = true; }

    public void markStarted(Map<String, Integer> initialScores)
    {
        this.state = State.IN_PROGRESS;
        applyScores(initialScores);
    }

    private void applyScores(Map<String, Integer> incoming)
    {
        if (incoming == null) return;
        for (Map.Entry<String, Integer> e : incoming.entrySet())
        {
            String display = resolveDisplayName(e.getKey());
            if (display == null) continue;
            this.scores.put(display, e.getValue() == null ? 0 : e.getValue());
        }
    }

    public void setCurrentQuestion(int index, String prompt, long deadline)
    {
        this.currentQuestionIndex = index;
        this.currentPrompt = prompt;
        this.currentDeadline = deadline;
        this.questionResolved = false;
        this.lastCorrectDisplay = null;
        this.lastCanonicalAnswer = null;
    }

    /**
     * Apply a QUESTION_RESOLVED. Updates running scores, derives who (if
     * anyone) got the question right from the results map, and marks the
     * question resolved so chat input stops being forwarded.
     *
     * @param results        results keyed by either normalized or display name
     * @param newScores      updated scores keyed by either form
     * @param canonicalAnswer the server's canonical answer (for UI/overhead)
     */
    public void applyResolution(
        Map<String, PerPlayerQuestionResult> results,
        Map<String, Integer> newScores,
        String canonicalAnswer)
    {
        applyScores(newScores);
        String correct = null;
        if (results != null)
        {
            for (Map.Entry<String, PerPlayerQuestionResult> e : results.entrySet())
            {
                PerPlayerQuestionResult r = e.getValue();
                if (r != null && r.correct)
                {
                    correct = resolveDisplayName(e.getKey());
                    break;
                }
            }
        }
        this.lastCanonicalAnswer = canonicalAnswer;
        this.lastCorrectDisplay = correct;
        this.questionResolved = true;
    }

    public void markComplete() { this.state = State.COMPLETE; }

    /** Count one more tick the local player has been outside the arena region. */
    public int incrementOutOfRegion() { return ++outOfRegionTicks; }
    /** Reset the out-of-region counter (called when player is in-region). */
    public void resetOutOfRegion() { outOfRegionTicks = 0; }
    public int getOutOfRegionTicks() { return outOfRegionTicks; }
}

package com.runetrivia.net;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.runetrivia.net.messages.Domain;
import com.runetrivia.net.messages.Messages;
import com.runetrivia.net.messages.Messages.Envelope;
import com.runetrivia.net.messages.Messages.HelloPayload;
import java.util.UUID;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.ScheduledThreadPoolExecutor;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicReference;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.WebSocket;
import okhttp3.WebSocketListener;
import okio.ByteString;

/**
 * WebSocket client for the RuneTrivia backend.
 * <ul>
 *   <li>Opens a persistent connection while the plugin is enabled
 *   <li>Sends HELLO on connect (with the local player's display name)
 *   <li>Heartbeats with PING every 20s; server is expected to reply PONG
 *   <li>Reconnects with exponential backoff on disconnect or error
 *   <li>Dispatches received messages to the supplied {@link Listener}
 * </ul>
 *
 * Threading: OkHttp fires listener callbacks on its own IO threads. We do
 * not marshal to the game/EDT thread here — that's the caller's job, since
 * different callers need different threads (panel = EDT, plugin core = game
 * thread for things that touch the client object).
 */
@Slf4j
public class TriviaWsClient
{
    public enum Status { DISCONNECTED, CONNECTING, CONNECTED }

    public interface Listener
    {
        /** Status transition. May fire on any thread. */
        void onStatusChange(Status status);

        /**
         * A parsed inbound envelope. payload is a Gson JsonElement; the listener
         * decides how to deserialize it based on `type`.
         */
        void onMessage(String type, String id, JsonElement payload);
    }

    private static final long HEARTBEAT_MS = 20_000;
    private static final long BACKOFF_INITIAL_MS = 1_000;
    private static final long BACKOFF_MAX_MS = 30_000;

    private final OkHttpClient http;
    private final Gson gson;
    private final ScheduledExecutorService scheduler;

    private final AtomicReference<WebSocket> socket = new AtomicReference<>();
    private final AtomicReference<Status> status = new AtomicReference<>(Status.DISCONNECTED);

    private volatile Listener listener;
    private volatile String url;
    private volatile String displayName;
    private volatile String pluginVersion = "0.0.1";
    private volatile boolean acceptingChallenges = true;
    private volatile boolean running = false;
    private long backoffMs = BACKOFF_INITIAL_MS;

    @Inject
    public TriviaWsClient(OkHttpClient http, Gson gson)
    {
        this.http = http;
        this.gson = gson;
        // Daemon so we don't block JVM shutdown.
        ScheduledThreadPoolExecutor exec = new ScheduledThreadPoolExecutor(1, r ->
        {
            Thread t = new Thread(r, "runetrivia-ws");
            t.setDaemon(true);
            return t;
        });
        exec.setRemoveOnCancelPolicy(true);
        this.scheduler = exec;
    }

    public void setListener(Listener listener)
    {
        this.listener = listener;
    }

    public Status getStatus()
    {
        return status.get();
    }

    public synchronized void start(String wsUrl, String displayName, boolean acceptingChallenges)
    {
        this.url = wsUrl;
        this.displayName = displayName;
        this.acceptingChallenges = acceptingChallenges;
        if (running)
        {
            return;
        }
        running = true;
        backoffMs = BACKOFF_INITIAL_MS;
        connect();
        scheduler.scheduleAtFixedRate(this::heartbeat, HEARTBEAT_MS, HEARTBEAT_MS, TimeUnit.MILLISECONDS);
    }

    public synchronized void stop()
    {
        running = false;
        WebSocket s = socket.getAndSet(null);
        if (s != null)
        {
            try
            {
                s.close(1000, "client_shutdown");
            }
            catch (Exception ignored)
            {
            }
        }
        setStatus(Status.DISCONNECTED);
    }

    /** Update the accepting-challenges flag and push a STATUS_UPDATE to the server (if connected). */
    public void updateAcceptingChallenges(boolean accepting)
    {
        this.acceptingChallenges = accepting;
        if (status.get() == Status.CONNECTED)
        {
            Messages.StatusUpdatePayload p = new Messages.StatusUpdatePayload();
            p.acceptingChallenges = accepting;
            send(Messages.TYPE_STATUS_UPDATE, p);
        }
    }

    public void updateDisplayName(String name)
    {
        this.displayName = name;
    }

    /**
     * Send a typed payload as a JSON envelope. No-op if not connected.
     */
    public <T> void send(String type, T payload)
    {
        WebSocket s = socket.get();
        if (s == null)
        {
            return;
        }
        Envelope<T> env = new Envelope<>();
        env.v = Domain.PROTOCOL_VERSION;
        env.type = type;
        env.id = UUID.randomUUID().toString();
        env.ts = System.currentTimeMillis();
        env.payload = payload;
        try
        {
            s.send(gson.toJson(env));
        }
        catch (Exception e)
        {
            log.warn("send {} failed", type, e);
        }
    }

    // -- internals ---------------------------------------------------------

    private void connect()
    {
        if (!running || url == null)
        {
            return;
        }
        setStatus(Status.CONNECTING);
        try
        {
            Request req = new Request.Builder().url(url).build();
            WebSocket s = http.newWebSocket(req, new Handler());
            socket.set(s);
        }
        catch (Exception e)
        {
            log.warn("failed to open WS to {}: {}", url, e.toString());
            scheduleReconnect();
        }
    }

    private void scheduleReconnect()
    {
        if (!running)
        {
            return;
        }
        setStatus(Status.DISCONNECTED);
        long delay = backoffMs;
        backoffMs = Math.min(backoffMs * 2, BACKOFF_MAX_MS);
        scheduler.schedule(this::connect, delay, TimeUnit.MILLISECONDS);
    }

    private void heartbeat()
    {
        if (status.get() != Status.CONNECTED)
        {
            return;
        }
        send(Messages.TYPE_PING, new Messages.PingPayload());
    }

    private void setStatus(Status s)
    {
        Status prev = status.getAndSet(s);
        if (prev != s)
        {
            Listener l = listener;
            if (l != null)
            {
                try
                {
                    l.onStatusChange(s);
                }
                catch (Exception e)
                {
                    log.warn("listener.onStatusChange threw", e);
                }
            }
        }
    }

    // -- handler -----------------------------------------------------------

    private class Handler extends WebSocketListener
    {
        @Override
        public void onOpen(WebSocket webSocket, Response response)
        {
            log.info("ws open: {}", url);
            backoffMs = BACKOFF_INITIAL_MS;
            setStatus(Status.CONNECTED);
            // Fire HELLO right away.
            HelloPayload hello = new HelloPayload();
            hello.displayName = displayName == null ? "Unknown" : displayName;
            hello.pluginVersion = pluginVersion;
            hello.acceptingChallenges = acceptingChallenges;
            send(Messages.TYPE_HELLO, hello);
        }

        @Override
        public void onMessage(WebSocket webSocket, String text)
        {
            try
            {
                JsonObject obj = gson.fromJson(text, JsonObject.class);
                String type = obj.has("type") ? obj.get("type").getAsString() : null;
                String id = obj.has("id") ? obj.get("id").getAsString() : null;
                JsonElement payload = obj.has("payload") ? obj.get("payload") : null;
                if (type == null)
                {
                    log.warn("dropping malformed frame: {}", text);
                    return;
                }
                Listener l = listener;
                if (l != null)
                {
                    l.onMessage(type, id, payload);
                }
            }
            catch (Exception e)
            {
                log.warn("failed to parse incoming frame: {}", text, e);
            }
        }

        @Override
        public void onMessage(WebSocket webSocket, ByteString bytes)
        {
            // We don't send binary frames; ignore.
        }

        @Override
        public void onClosing(WebSocket webSocket, int code, String reason)
        {
            log.info("ws closing: {} {}", code, reason);
        }

        @Override
        public void onClosed(WebSocket webSocket, int code, String reason)
        {
            log.info("ws closed: {} {}", code, reason);
            socket.compareAndSet(webSocket, null);
            scheduleReconnect();
        }

        @Override
        public void onFailure(WebSocket webSocket, Throwable t, Response response)
        {
            log.info("ws failure: {}", t.toString());
            socket.compareAndSet(webSocket, null);
            scheduleReconnect();
        }
    }
}

package com.runetrivia.net.messages;

/**
 * Shared structural types mirroring shared/src/domain.ts. Nested static
 * classes (rather than separate files) so the protocol surface lives in
 * two files — see also {@link Messages}.
 */
public final class Domain
{
    public static final int PROTOCOL_VERSION = 1;

    private Domain()
    {
    }

    /** Plain world-coord tuple. Mirrored manually because net.runelite.api.coords.WorldPoint isn't Gson-friendly. */
    public static final class WorldPoint
    {
        public int x;
        public int y;
        public int plane;

        public WorldPoint()
        {
        }

        public WorldPoint(int x, int y, int plane)
        {
            this.x = x;
            this.y = y;
            this.plane = plane;
        }
    }

    public static final class ArenaProposal
    {
        public int regionId;
        public WorldPoint npcTile;
        public WorldPoint challengerTile;
        public WorldPoint challengedTile;
    }

    public static final class HostNpc
    {
        public int npcId;
        public String displayName;
        public WorldPoint tile;
    }

    public static final class PerPlayerQuestionResult
    {
        public String text;
        public boolean correct;
        public Long responseMs;
    }
}

package com.runetrivia.net.messages;

import com.runetrivia.net.messages.Domain.ArenaProposal;
import com.runetrivia.net.messages.Domain.HostNpc;
import com.runetrivia.net.messages.Domain.PerPlayerQuestionResult;
import com.runetrivia.net.messages.Domain.WorldPoint;
import java.util.Map;

/**
 * Wire-protocol payloads, mirrored from shared/src/protocol.ts. Any change
 * to that file should be reflected here in the same commit.
 *
 * Convention: each payload is a plain Java class with public fields. Gson
 * populates them via reflection; no constructors or setters needed for
 * deserialization. We construct outbound payloads via the static helpers
 * at the bottom of this class.
 */
public final class Messages
{
    private Messages()
    {
    }

    // -- Envelope ----------------------------------------------------------

    /**
     * Generic message envelope. Outbound envelopes use the concrete payload
     * class as T; inbound envelopes start as Envelope<JsonElement> and the
     * dispatcher reparses payload based on the type field.
     */
    public static final class Envelope<T>
    {
        public int v;
        public String type;
        public String id;
        public long ts;
        public T payload;
    }

    // -- Message-type discriminators (mirrors shared/src/protocol.ts) -----

    public static final String TYPE_HELLO = "HELLO";
    public static final String TYPE_WELCOME = "WELCOME";
    public static final String TYPE_STATUS_UPDATE = "STATUS_UPDATE";
    public static final String TYPE_PING = "PING";
    public static final String TYPE_PONG = "PONG";
    public static final String TYPE_ERROR = "ERROR";

    public static final String TYPE_CHALLENGE_CREATE = "CHALLENGE_CREATE";
    public static final String TYPE_CHALLENGE_CREATED = "CHALLENGE_CREATED";
    public static final String TYPE_CHALLENGE_OFFERED = "CHALLENGE_OFFERED";
    public static final String TYPE_CHALLENGE_RESPOND = "CHALLENGE_RESPOND";
    public static final String TYPE_CHALLENGE_RESOLVED = "CHALLENGE_RESOLVED";
    public static final String TYPE_CHALLENGE_CANCEL = "CHALLENGE_CANCEL";

    public static final String TYPE_ARENA_STAGED = "ARENA_STAGED";
    public static final String TYPE_PLAYER_READY = "PLAYER_READY";

    public static final String TYPE_MATCH_STARTED = "MATCH_STARTED";
    public static final String TYPE_QUESTION_DELIVERED = "QUESTION_DELIVERED";
    public static final String TYPE_ANSWER_SUBMIT = "ANSWER_SUBMIT";
    public static final String TYPE_QUESTION_RESOLVED = "QUESTION_RESOLVED";
    public static final String TYPE_MATCH_COMPLETED = "MATCH_COMPLETED";
    public static final String TYPE_MATCH_FORFEIT = "MATCH_FORFEIT";
    public static final String TYPE_BANTER = "BANTER";

    // Anti-cheat (Phase 7)
    public static final String TYPE_WIKI_TRIGGERED = "WIKI_TRIGGERED";
    public static final String TYPE_SHAME_PLAYER = "SHAME_PLAYER";

    // -- Lifecycle payloads -----------------------------------------------

    public static final class HelloPayload
    {
        public String displayName;
        public String pluginVersion;
        public boolean acceptingChallenges;
    }

    public static final class WelcomePayload
    {
        public String serverVersion;
        public WelcomePayloadYou you;
    }

    public static final class WelcomePayloadYou
    {
        public String displayName;
    }

    public static final class StatusUpdatePayload
    {
        public boolean acceptingChallenges;
    }

    public static final class PingPayload
    {
    }

    public static final class PongPayload
    {
    }

    public static final class ErrorPayload
    {
        public String code;
        public String message;
        public String refId;
    }

    // -- Challenge payloads -----------------------------------------------

    public static final class ChallengeCreatePayload
    {
        public String targetDisplayName;
        public WorldPoint challengerLocation;
        public ArenaProposal proposedArena;
    }

    public static final class ChallengeCreatedPayload
    {
        public String challengeId;
        public String targetDisplayName;
        public long expiresAt;
    }

    public static final class ChallengeOfferedPayload
    {
        public String challengeId;
        public String fromDisplayName;
        public long expiresAt;
        public ArenaProposal proposedArena;
    }

    public static final class ChallengeRespondPayload
    {
        public String challengeId;
        public boolean accept;
    }

    public static final class ChallengeResolvedPayload
    {
        public String challengeId;
        public boolean accepted;
        public String matchId;
        public String reason;
    }

    public static final class ChallengeCancelPayload
    {
        public String challengeId;
    }

    // -- Staging payloads -------------------------------------------------

    public static final class ArenaStagedPayload
    {
        public String matchId;
